/**
 * 演示模块：把用户提供的相对路径解析到工作区根目录下。
 */

/** 解析路径：拒绝绝对路径与 ../ 穿越，其余按工作区内相对路径拼接。 */
export function resolveInside(root, userPath) {
  const raw = String(userPath)
  if (!raw.trim()) throw new Error('路径不能为空')
  if (raw.startsWith('/') || raw.startsWith('\\') || /^[A-Za-z]:/.test(raw)) {
    throw new Error(`拒绝绝对路径：${raw}`)
  }
  const parts = raw.split(/[\\/]+/).filter((p) => p.length > 0)
  if (parts.includes('..')) throw new Error(`拒绝路径穿越：${raw}`)
  return `${root}/${parts.join('/')}`
}
